// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzz the from address and v, and an indicator whether we pass an empty array
    function testFuzz_property(address from, uint256 v, bool makeEmpty) public {
        // Keep domain wide; no restrictive assumes needed.
        address counterparty = address(this); // we will not rely on external behaviour for this property

        // Prepare the tos array: if makeEmpty == true, pass an empty array which should cause REVERT in correct C
        address[] memory tos;
        if (makeEmpty) {
            tos = new address[](0);
        } else {
            tos = new address[](1);
            tos[0] = address(0xBEEF);
        }

        bool ok;
        try c.transfer(from, counterparty, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for ANY inputs, when _tos is empty the reference CONTRACT reverts (ok == false).
        // The mutant that changes require(_tos.length > 0) to >= 0 will allow empty arrays and make ok == true
        if (makeEmpty) {
            assertTrue(!ok);
        } else {
            // when not empty, both reference and mutant allow success; we don't require a particular result here
            assertTrue(ok);
        }
    }
}
